
import React, { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import "./Students.css";

const importAll = (r) => r.keys().map(r);
const images = importAll(
  require.context("/public/images/studentWorks", false, /\.(png|jpe?g|svg)$/)
);

const Students = () => {
  const { t } = useTranslation();
  const [visibleRows, setVisibleRows] = useState(2);
  const [selectedIndex, setSelectedIndex] = useState(null);
  const imagesPerRow = 3;

  const showMoreImages = () => {
    setVisibleRows((prev) => prev + 2);
  };

  const openModal = (index) => {
    setSelectedIndex(index);
  };

  const closeModal = () => {
    setSelectedIndex(null);
  };

  const nextImage = () => {
    setSelectedIndex((prev) => (prev === null ? 0 : (prev + 1) % images.length));
  };

  const prevImage = () => {
    setSelectedIndex((prev) =>
      prev === null ? images.length - 1 : (prev - 1 + images.length) % images.length
    );
  };

  useEffect(() => {
    const onKey = (e) => {
      if (selectedIndex === null) return;
      if (e.key === "Escape") closeModal();
      else if (e.key === "ArrowRight") nextImage();
      else if (e.key === "ArrowLeft") prevImage();
    };

    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [selectedIndex]);

  const renderImages = () => {
    const visibleImages = images.slice(0, visibleRows * imagesPerRow);
    return visibleImages.map((image, index) => (
      <img
        key={index}
        src={image}
        alt=""
        className="gallery-image"
        onClick={() => openModal(index)}
      />
    ));
  };

  return (
    <div className="image-gallery" style={{ padding: "0 0 30px 0" }}>
      <div className="image-grid">{renderImages()}</div>

      {visibleRows * imagesPerRow < images.length && (
        <button className="show-more-button" onClick={showMoreImages}>
          {t("show-more")}
        </button>
      )}

      {selectedIndex !== null && (
        <div className="modal-window-image" onClick={closeModal}>
          <div className="modal-image-content" onClick={(e) => e.stopPropagation()}>
            <button className="modal-arrow left" onClick={prevImage} aria-label={t("gallery-prev")}>
              ‹
            </button>

            <div className="modal-photo-frame">
              <img src={images[selectedIndex]} alt="" className="modal-image" />

              <button
                className="modal-close-unique"
                onClick={closeModal}
                aria-label={t("gallery-close")}
              />
            </div>

            <button className="modal-arrow right" onClick={nextImage} aria-label={t("gallery-next")}>
              ›
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Students;
