import React, { useState, useRef, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import './Carousel.css';

const importAll = (r) => r.keys().map(r);
const rotateImages = (items, offset) => {
  if (!items.length) return items;
  const normalizedOffset = ((offset % items.length) + items.length) % items.length;
  return [...items.slice(normalizedOffset), ...items.slice(0, normalizedOffset)];
};

const menImages = importAll(require.context('/public/images/menHaircuts', false, /\.(png|jpe?g|svg)$/));
const womenImages = importAll(require.context('/public/images/womenHaircuts', false, /\.(png|jpe?g|svg)$/));
const hairstylesImages = importAll(require.context('/public/images/hairstyles', false, /\.(png|jpe?g|svg)$/));

const images = [...menImages, ...womenImages, ...hairstylesImages];

const Carousel = ({ direction = 'right', startOffset = 0 }) => {
  const { t } = useTranslation();
  const carouselRef = useRef(null);
  const [isHovered, setIsHovered] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(null);
  const orderedImages = rotateImages(images, startOffset);

  const positionRef = useRef(0);
  const velocity = 0.07;
  const frameRef = useRef(null);

  const closeModal = () => setSelectedIndex(null);
  const nextImage = () => setSelectedIndex((prev) => (prev + 1) % orderedImages.length);
  const prevImage = () =>
    setSelectedIndex((prev) => (prev - 1 + orderedImages.length) % orderedImages.length);

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (selectedIndex !== null && e.key === 'Escape') closeModal();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedIndex]);

  useEffect(() => {
    const carousel = carouselRef.current;
    if (!carousel) return;

    positionRef.current =
      direction === 'left'
        ? carousel.scrollWidth / 2
        : (carousel.scrollWidth / 2 / Math.max(orderedImages.length, 1)) * startOffset;
    carousel.scrollLeft = positionRef.current;

    let lastTime = performance.now();

    const animate = (now) => {
      const delta = now - lastTime;
      lastTime = now;

      if (!isHovered && carousel.scrollWidth > carousel.clientWidth) {
        const scrollAmount = velocity * delta * (direction === 'left' ? -1 : 1);
        positionRef.current += scrollAmount;

        if (positionRef.current >= carousel.scrollWidth / 2) {
          positionRef.current = 0;
        } else if (positionRef.current <= 0) {
          positionRef.current = carousel.scrollWidth / 2;
        }

        carousel.scrollLeft = positionRef.current;
      }

      frameRef.current = requestAnimationFrame(animate);
    };

    frameRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(frameRef.current);
  }, [direction, isHovered, orderedImages.length, startOffset]);

  return (
    <div
      className="carousel-container"
      ref={carouselRef}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div className="carousel-content">
        {}
        {[...orderedImages, ...orderedImages].map((image, index) => (
          <img
            key={index}
            src={image}
            className="carousel-image"
            onClick={() => setSelectedIndex(index % orderedImages.length)}
            alt=""
            loading="lazy"
          />
        ))}
      </div>

      {}
      {selectedIndex !== null && (
        <div className="modal-window-image" onClick={closeModal}>
          <div
            className="modal-image-content"
            onClick={(e) => e.stopPropagation()}
          >
            <button className="modal-arrow left" onClick={prevImage} aria-label={t("gallery-prev")}>‹</button>
            <div className="modal-photo-frame">
              <img
                src={orderedImages[selectedIndex]}
                alt=""
                className="modal-image"
              />
              <button
                className="modal-close-unique"
                onClick={closeModal}
                aria-label={t("gallery-close")}
              ></button>
            </div>
            <button className="modal-arrow right" onClick={nextImage} aria-label={t("gallery-next")}>›</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Carousel;
